import{_ as t,o,c as s,a2 as a}from"./chunks/framework.CpZKh-tG.js";const p=JSON.parse('{"title":"Image hero+gallery inventory — Phase 0 of #5 rework","description":"","frontmatter":{},"headers":[],"relativePath":"provenance/image-hero-inventory.md","filePath":"provenance/image-hero-inventory.md"}'),i={name:"provenance/image-hero-inventory.md"};function r(n,e,d,l,c,h){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="image-hero-gallery-inventory-—-phase-0-of-5-rework" tabindex="-1">Image hero+gallery inventory — Phase 0 of #5 rework <a class="header-anchor" href="#image-hero-gallery-inventory-—-phase-0-of-5-rework" aria-label="Permalink to &quot;Image hero+gallery inventory — Phase 0 of #5 rework&quot;">​</a></h1><p><em>Generated June 2026. Pre-rework snapshot. Read alongside <code>docs/guides/post-332-follow-ups.md</code> §5.</em></p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>Eleven detail-panel surfaces that follow a hero+gallery pattern were audited for hero-file coverage, provenance consistency, and refactor remnants.</p><h2 id="per-surface-inventory" tabindex="-1">Per-surface inventory <a class="header-anchor" href="#per-surface-inventory" aria-label="Permalink to &quot;Per-surface inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th style="text-align:right;">Entities on disk</th><th style="text-align:right;">Hero coverage</th><th>Pattern</th></tr></thead><tbody><tr><td>Missions</td><td style="text-align:right;">233 hero files + 58 gallery dirs (old) + 24 gallery dirs (new)</td><td style="text-align:right;"><strong>24 missing</strong> (Slice A/B/C)</td><td><code>missions/&lt;id&gt;.jpg</code> for hero; gallery split between <code>missions/&lt;id&gt;/</code> (old) and <code>mission-galleries/&lt;id&gt;/</code> (new)</td></tr><tr><td>Fleet</td><td style="text-align:right;">236 entity dirs</td><td style="text-align:right;">100% (236 / 236)</td><td><code>fleet-galleries/&lt;id&gt;/01.jpg</code> for both hero + first gallery slot</td></tr><tr><td>Moon sites</td><td style="text-align:right;">16</td><td style="text-align:right;">100%</td><td><code>moon-sites/&lt;id&gt;/01.jpg</code></td></tr><tr><td>Mars sites</td><td style="text-align:right;">25</td><td style="text-align:right;">100%</td><td><code>mars-sites/&lt;id&gt;/01.jpg</code></td></tr><tr><td>Earth objects</td><td style="text-align:right;">13</td><td style="text-align:right;">100%</td><td><code>earth-objects/&lt;id&gt;/01.jpg</code></td></tr><tr><td>Planets</td><td style="text-align:right;">8</td><td style="text-align:right;">100%</td><td><code>planets/&lt;id&gt;/01.jpg</code></td></tr><tr><td>Satellites</td><td style="text-align:right;">16</td><td style="text-align:right;">100%</td><td><code>satellites/&lt;id&gt;/01.jpg</code></td></tr><tr><td>Small bodies</td><td style="text-align:right;">8</td><td style="text-align:right;">100%</td><td><code>small-bodies/&lt;id&gt;/01.jpg</code></td></tr><tr><td>ISS modules</td><td style="text-align:right;">24</td><td style="text-align:right;">100%</td><td><code>iss-modules/&lt;id&gt;/01.jpg</code></td></tr><tr><td>Tiangong modules</td><td style="text-align:right;">6</td><td style="text-align:right;">100%</td><td><code>tiangong-modules/&lt;id&gt;/01.jpg</code></td></tr><tr><td>Sun</td><td style="text-align:right;">1 (single entity, 20 gallery files flat)</td><td style="text-align:right;">n/a</td><td><code>sun/&lt;nn&gt;.jpg</code></td></tr></tbody></table><p><strong>Missions is the only surface with a hero gap, and the gap is structural — a 24-entry cohort with three sequential follow-up steps all skipped.</strong></p><h2 id="the-24-mission-hero-gap-—-root-cause" tabindex="-1">The 24-mission hero gap — root cause <a class="header-anchor" href="#the-24-mission-hero-gap-—-root-cause" aria-label="Permalink to &quot;The 24-mission hero gap — root cause&quot;">​</a></h2><p>Slice A/B/C (commits <code>62c35a0da</code>, <code>45f668cd4</code>, <code>f4ee2e15d</code> on main — &quot;feat(missions + fleet)&quot;) added 24 missions to the catalog via the new <code>static/images/mission-galleries/&lt;id&gt;/</code> directory pattern. Three follow-up steps that the older <code>static/images/missions/&lt;id&gt;/</code> flow includes were skipped:</p><ol><li><strong>Hero staging:</strong> the cover image at <code>static/images/missions/&lt;id&gt;.jpg</code> was never copied from the gallery. Card UI references that path; the <code>onerror=&quot;cover-missing&quot;</code> handler hides the figure gracefully but the cards lose their visual identity.</li><li><strong>Provenance registration:</strong> none of the gallery files in <code>mission-galleries/</code> were added to <code>static/data/image-provenance.json</code>. This shows up as 491 orphan files on disk vs 0 broken-reference entries in the manifest (the manifest is internally consistent but silent on a whole subtree of the corpus).</li><li><strong>Vision scoring:</strong> because the gallery isn&#39;t in provenance, <code>scripts/score-images.ts</code> never sees these files. They have no entry in <code>static/data/image-vision.json</code> and no pre-cropped variants (<code>.1x1.jpg</code> / <code>.4x3.jpg</code> / <code>.16x9.jpg</code>).</li></ol><h3 id="the-24-affected-mission-ids" tabindex="-1">The 24 affected mission ids <a class="header-anchor" href="#the-24-affected-mission-ids" aria-label="Permalink to &quot;The 24 affected mission ids&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apollo-1     apollo-soyuz    inspiration4   mariner10</span></span>
<span class="line"><span>otv-1        otv-2           otv-3          otv-4</span></span>
<span class="line"><span>otv-5        otv-6           otv-7          polaris-dawn</span></span>
<span class="line"><span>shenzhou-1   skylab-2        skylab-3       skylab-4</span></span>
<span class="line"><span>voskhod-1    voskhod-2       vostok-1       vostok-2</span></span>
<span class="line"><span>vostok-3     vostok-4        vostok-5       vostok-6</span></span></code></pre></div><h2 id="provenance-↔-disk-consistency" tabindex="-1">Provenance ↔ disk consistency <a class="header-anchor" href="#provenance-↔-disk-consistency" aria-label="Permalink to &quot;Provenance ↔ disk consistency&quot;">​</a></h2><ul><li><strong><code>static/data/image-provenance.json</code> entries:</strong> 4241</li><li><strong>Broken references (path in JSON but file missing on disk):</strong> 0</li><li><strong>Disk source files (non-variant):</strong> 2300</li><li><strong>Disk source files registered in provenance:</strong> 1809</li><li><strong>Disk orphans (file exists but not in provenance):</strong> 491 — 100% in <code>mission-galleries/</code>, matching the Slice A/B/C cohort above.</li></ul><p>The manifest itself is clean. The data hygiene gap is <strong>absence</strong>, not wrongness — 491 files live outside the only system that scores them.</p><h2 id="pattern-inconsistencies-worth-flagging" tabindex="-1">Pattern inconsistencies worth flagging <a class="header-anchor" href="#pattern-inconsistencies-worth-flagging" aria-label="Permalink to &quot;Pattern inconsistencies worth flagging&quot;">​</a></h2><ul><li><strong>Hero-path convention:</strong> missions use <code>&lt;surface&gt;/&lt;id&gt;.jpg</code> (a top- level file). Every other surface uses <code>&lt;surface&gt;/&lt;id&gt;/01.jpg</code> (a slot inside the gallery dir). The mission outlier is what made the Slice A/B/C skip possible — the staging step has no equivalent on the other surfaces because the first gallery slot <em>is</em> the hero.</li><li><strong>Variant filename convention:</strong> old pattern uses <code>01.16x9.jpg</code> (dot separator). Slice A/B/C <code>mission-galleries/</code> uses <code>01-16x9.jpg</code> (dash separator). Pipeline tooling that grep-matches one form silently skips the other.</li></ul><p>Both inconsistencies are fixable in the rework (collapse missions onto the universal <code>&lt;surface&gt;/&lt;id&gt;/01.jpg</code> pattern, standardise on dot or dash) but are independent of the hero-quality problem and shouldn&#39;t be mixed into the same change without a separate review.</p><h2 id="what-phase-1-needs-to-handle" tabindex="-1">What Phase 1 needs to handle <a class="header-anchor" href="#what-phase-1-needs-to-handle" aria-label="Permalink to &quot;What Phase 1 needs to handle&quot;">​</a></h2><p>Per the rubric locked in chat (see §&quot;HERO CRITERIA&quot;), the audit script needs to evaluate every entity × surface for:</p><ol><li><strong>Hero existence</strong> — does the file at the conventional hero path exist? (Catches the 24-mission cohort + any future skipped staging.)</li><li><strong>Provenance coverage</strong> — is the hero registered? (Catches the orphan-corpus class.)</li><li><strong>Hero quality</strong> — pulls existing score from <code>image-vision.json</code>, applies the eight-point hero rubric (subject / composition / context / render policy / no-deny-list / recognition / prefer-alternate / cross-surface), emits per-surface audit markdown.</li><li><strong>Cross-surface consistency</strong> — flags assets that appear under both a mission and a fleet entry (BepiColombo, Juno, SLIM noted in chat) so the same canonical hero resolves for both.</li></ol><p>Output: one <code>docs/provenance/&lt;surface&gt;-hero-audit.md</code> per surface covering auto-swap proposals, needs-curation queue, and accepted overrides — same format as the existing <code>fleet-hero-audit.md</code> but emitted from one shared script driven by a per-surface config.</p><h2 id="budget-plan" tabindex="-1">Budget plan <a class="header-anchor" href="#budget-plan" aria-label="Permalink to &quot;Budget plan&quot;">​</a></h2><ul><li><strong>Phase 1 (audit infrastructure):</strong> $0 — no API calls, uses existing manifest data + algorithmic post-filter.</li><li><strong>Phase 2 (operator review):</strong> $0 — Marko reads the per-surface markdowns, marks them up.</li><li><strong>Phase 3 (targeted rescore with hero rubric):</strong> $1-4 worst case — bump <code>SCORING_PROMPT_VERSION</code> to v1.1, extend the prompt to return a <code>hero_score</code> field alongside <code>score</code>, re-run <strong>only on Phase 2&#39;s flagged candidates</strong> (estimated 50-150 images).</li><li><strong>Phase 4 (sourcing the missing):</strong> $0 — agency-first fetcher pattern (Wikimedia / NASA Image Library / agency archives), applied to the Phase 1 needs-curation queue + the 24-mission backlog from this report.</li><li><strong>Phase 5 (frontend wiring):</strong> $0 — replace hardcoded image-path references with <code>pickHero(surface, id)</code> that reads the audit- approved manifest + an optional <code>&lt;surface&gt;-hero-overrides.json</code>.</li></ul><p>Total expected: <strong>&lt; $5 USD</strong>. Hard ceiling per Marko: $20 USD.</p><hr><p><em>This inventory file is the artefact for Phase 0. Phase 1 (the generalised audit script) will be drafted next; outline + sample output will land here before any code is committed.</em></p>`,27)])])}const u=t(i,[["render",r]]);export{p as __pageData,u as default};
